def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            shape = {(y-r0, x-c0) for y,x in cells}
            objs.append((r0,c0,color,shape,r1-r0+1,c1-c0+1))

    out = [[0]*w for _ in range(h)]
    # Organize objects by their original top-to-bottom order into compact rows,
    # preserving each object's shape and color.
    objs.sort(key=lambda o: (o[0], o[1]))
    # The puzzle's objects are arranged in a 3-cell-high lattice, with upper
    # objects placed at the top and lower objects at the bottom.
    for r0,c0,color,shape,oh,ow in objs:
        nr, nc = r0, c0
        if oh <= h and ow <= w:
            for y,x in shape:
                out[nr+y][nc+x] = color
    return out
